using System;
using System.IO;
using System.Linq;
using UnityEngine;
using UnityEditor;
using UnityEditor.SceneManagement;
using UnityEngine.SceneManagement;
namespace Snowglow.Editor {
 public static class MachineryAudioAuthoring {
 const string Clips="Assets/Snowglow/Audio/Machinery/Recorded/",Logs="Logs/MachineryAudio",Request="Logs/InstallMachineryAudio.request";static int assertions;
 static void Check(bool ok,string text){if(!ok)throw new InvalidOperationException("Machinery audio: "+text);assertions++;}
 static T[] All<T>(Scene s)where T:Component=>s.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<T>(true)).ToArray();
 [InitializeOnLoadMethod]static void Register(){EditorApplication.update+=Pending;}
 static void Pending(){if(!File.Exists(Request)){EditorApplication.update-=Pending;return;}if(EditorApplication.isCompiling||EditorApplication.isUpdating||EditorApplication.isPlayingOrWillChangePlaymode)return;EditorApplication.update-=Pending;File.Delete(Request);try{Install();}catch(Exception e){Directory.CreateDirectory(Logs);File.WriteAllText(Logs+"/Validation.txt","FAIL: "+e);Debug.LogException(e);}}
 static AudioSource Source(SynthAudio audio,AudioSource existing,string name,string clip,float priority){if(!existing){var go=new GameObject(name);go.transform.SetParent(audio.transform,false);existing=go.AddComponent<AudioSource>();}existing.clip=AssetDatabase.LoadAssetAtPath<AudioClip>(Clips+clip+".wav");Check(existing.clip,"clip missing "+clip);existing.playOnAwake=false;existing.loop=true;existing.volume=0;existing.pitch=1;existing.spatialBlend=0;existing.dopplerLevel=0;existing.priority=(int)priority;existing.ignoreListenerPause=false;existing.mute=audio.effects&&audio.effects.mute;EditorUtility.SetDirty(existing);return existing;}
 static MachineryAudioProfile Profile(string machine)=>new MachineryAudioProfile{idle=AssetDatabase.LoadAssetAtPath<AudioClip>(Clips+machine+"-idle.wav"),work=AssetDatabase.LoadAssetAtPath<AudioClip>(Clips+machine+"-work.wav"),drive=AssetDatabase.LoadAssetAtPath<AudioClip>(Clips+machine+"-drive.wav")};
 public static void Bind(SynthAudio audio){audio.tractorAudio=Profile("tractor");audio.loaderAudio=Profile("loader");audio.brakingClip=AssetDatabase.LoadAssetAtPath<AudioClip>(Clips+"brake-air.wav");audio.motor=Source(audio,audio.motor,"Engine | recorded diesel","tractor-idle",80);audio.motorLoad=Source(audio,audio.motorLoad,"Engine | recorded work","tractor-work",90);audio.transmission=Source(audio,audio.transmission,"Drivetrain | recorded mechanical texture","tractor-drive",100);audio.brakeAir=Source(audio,audio.brakeAir,"Braking | short pneumatic cue","brake-air",75);audio.brakeAir.loop=false;EditorUtility.SetDirty(audio.brakeAir);EditorUtility.SetDirty(audio);}
 static void ClipCheck(AudioClip clip){Check(clip.channels==1&&clip.frequency==24000,"mono/sample rate");var data=new float[clip.samples];Check(clip.GetData(data,0),"clip data unavailable");float max=0,step=0;double sum=0;for(int i=0;i<data.Length;i++){max=Mathf.Max(max,Mathf.Abs(data[i]));sum+=data[i]*data[i];if(i>0)step=Mathf.Max(step,Mathf.Abs(data[i]-data[i-1]));}Check(max<=.651f&&max>.5f,"PCM peak outside headroom");Check(sum/data.Length>.01,"silent clip");Check(Mathf.Abs(data[0]-data[data.Length-1])<=step*1.02f,"loop boundary discontinuity");}
 static void CurveChecks(SynthAudio saved,MachineController[] fleet){
 var idle=SynthAudio.CalculateMix(0,0,0,0,false);var cruise=SynthAudio.CalculateMix(.7f,.6f,.1f,.7f,false);var work=SynthAudio.CalculateMix(.2f,1,1,.3f,false);var light=SynthAudio.CalculateMix(.2f,1,0,.3f,false);Check(idle.engineVolume>0&&idle.transmissionVolume==0&&idle.loadVolume==0,"audible idle, silent idle gears");Check(cruise.enginePitch>idle.enginePitch&&cruise.transmissionVolume>0,"speed response");Check(work.engineVolume>light.engineVolume&&work.loadVolume>light.loadVolume&&work.enginePitch<light.enginePitch,"struggle grows volume with RPM droop");Check(SynthAudio.CalculateMix(.7f,.6f,.1f,.7f,true).enginePitch<cruise.enginePitch,"loader heavier tuning");
 foreach(bool loader in new[]{false,true})for(int speed=0;speed<=10;speed++)for(int load=0;load<=10;load++){var m=SynthAudio.CalculateMix(speed/10f,1,load/10f,speed/10f,loader);Check(m.enginePitch>=.5f&&m.enginePitch<=2&&m.transmissionPitch>=.5f&&m.transmissionPitch<=2,"pitch limits");Check(m.engineVolume+m.loadVolume+m.transmissionVolume<.6f,"layer headroom");}
 var fixture=new GameObject("Audio validation fixture"){hideFlags=HideFlags.HideAndDontSave};GameObject machineObject=null;
 try{var audio=fixture.AddComponent<SynthAudio>();audio.effects=fixture.AddComponent<AudioSource>();audio.ambience=fixture.AddComponent<AudioSource>();audio.reverseAlarm=fixture.AddComponent<AudioSource>();audio.reverseAlarm.clip=saved.reverseAlarm.clip;Bind(audio);
 foreach(var sourceMachine in fleet){machineObject=new GameObject("Audio machine fixture"){hideFlags=HideFlags.HideAndDontSave};var machine=machineObject.AddComponent<MachineController>();machine.definition=sourceMachine.definition;machine.equipment=sourceMachine.equipment;machine.Tool=machineObject.AddComponent<AttachmentController>();machine.wheels=Array.Empty<WheelCollider>();machine.ActiveMachine=true;machine.Fuel=10;machine.Condition=100;
 for(int n=0;n<180;n++)audio.UpdateMachinery(machine,0,0,true,1f/60);float idleVolume=audio.motor.volume,idlePitch=audio.motor.pitch;Check(audio.MachineryOperating&&idleVolume>.05f&&audio.transmission.volume==0,"runtime idle");
 for(int n=0;n<180;n++)audio.UpdateMachinery(machine,1,0,true,1f/60);Check(audio.Workload>.65f&&audio.motorLoad.volume>.08f&&audio.motor.volume>idleVolume,"stationary pushing strain");machine.Speed=machine.definition.maxSpeed*.8f;for(int n=0;n<180;n++)audio.UpdateMachinery(machine,.7f,0,true,1f/60);Check(audio.motor.pitch>idlePitch&&audio.transmission.volume>.02f,"runtime driving mix");
 audio.SetMuted(true);Check(audio.motor.mute&&audio.motorLoad.mute&&audio.transmission.mute&&audio.brakeAir.mute&&audio.reverseAlarm.mute&&audio.effects.mute&&audio.ambience.mute,"mute all sources");audio.SetMuted(false);Check(!audio.motor.mute&&!audio.transmission.mute&&!audio.motorLoad.mute&&!audio.brakeAir.mute&&!audio.reverseAlarm.mute,"unmute all loops");
 Check(audio.motor.clip==(sourceMachine.definition.loader?audio.loaderAudio.idle:audio.tractorAudio.idle),"machine-specific recorded profile");
 audio.UpdateMachinery(machine,0,1,true,.02f);Check(audio.BrakeCueTriggered,"moving brake press triggers cue");audio.UpdateMachinery(machine,0,1,true,.02f);Check(!audio.BrakeCueTriggered,"held brake does not retrigger");audio.UpdateMachinery(machine,0,0,true,.02f);audio.UpdateMachinery(machine,0,1,true,.02f);Check(!audio.BrakeCueTriggered,"brake cue cooldown");
 audio.UpdateMachinery(machine,1,0,false,.02f);Check(!audio.MachineryOperating&&audio.motor.volume==0&&audio.motorLoad.volume==0&&audio.transmission.volume==0,"pause silence");audio.UpdateMachinery(machine,1,0,true,.02f);machine.Fuel=0;audio.UpdateMachinery(machine,1,0,true,.02f);Check(!audio.MachineryOperating&&audio.motor.volume==0,"empty fuel silence");machine.Fuel=10;machine.Condition=0;audio.UpdateMachinery(machine,1,0,true,.02f);Check(!audio.MachineryOperating,"broken machine silence");machine.Condition=100;machine.ActiveMachine=false;audio.UpdateMachinery(machine,1,0,true,.02f);Check(!audio.MachineryOperating,"parked silence");machine.ActiveMachine=true;audio.UpdateMachinery(machine,1,0,true,.02f);audio.SendMessage("OnDisable");Check(!audio.MachineryOperating&&audio.motor.volume==0,"disable stops loops");UnityEngine.Object.DestroyImmediate(machineObject);machineObject=null;
 }
 }finally{if(machineObject)UnityEngine.Object.DestroyImmediate(machineObject);UnityEngine.Object.DestroyImmediate(fixture);}
 }
 [MenuItem("Snowglow/Audio/Install load responsive machinery audio")]
 public static void Install(){assertions=0;var scene=SceneManager.GetActiveScene();Check(scene.path==SceneValidation.ScenePath&&!EditorApplication.isPlayingOrWillChangePlaymode,"open Pinefall with Play stopped");SceneValidation.Validate(scene);Directory.CreateDirectory(Logs);if(!File.Exists(Logs+"/Pinefall-before.unity"))EditorSceneManager.SaveScene(scene,Logs+"/Pinefall-before.unity",true);else if(scene.isDirty)EditorSceneManager.SaveScene(scene,Logs+"/Pinefall-unsaved-before.unity",true);var session=All<PrototypeSession>(scene).Single();var seedPath=AssetDatabase.GetAssetPath(session.Snow.seed);var seedHash=AssetDatabase.GetAssetDependencyHash(seedPath);var poses=All<CatalogPlacement>(scene).ToDictionary(p=>GlobalObjectId.GetGlobalObjectIdSlow(p).ToString(),p=>p.transform.localToWorldMatrix.ToString("R"));var fleetPoses=session.Fleet.Select(m=>m.transform.localToWorldMatrix.ToString("R")).ToArray();string alarm=AssetDatabase.GetAssetPath(session.Audio.reverseAlarm.clip);float alarmVolume=session.Audio.reverseAlarm.volume;
 foreach(string clip in new[]{"tractor-idle","tractor-work","tractor-drive","loader-idle","loader-work","loader-drive","brake-air"}){string path=Clips+clip+".wav";AssetDatabase.ImportAsset(path,ImportAssetOptions.ForceSynchronousImport);var importer=(AudioImporter)AssetImporter.GetAtPath(path);var settings=importer.defaultSampleSettings;settings.loadType=AudioClipLoadType.DecompressOnLoad;settings.compressionFormat=AudioCompressionFormat.PCM;settings.preloadAudioData=true;settings.sampleRateSetting=AudioSampleRateSetting.PreserveSampleRate;importer.defaultSampleSettings=settings;importer.SaveAndReimport();ClipCheck(AssetDatabase.LoadAssetAtPath<AudioClip>(path));}
 Bind(session.Audio);AssetDatabase.SaveAssets();SceneValidation.Validate(scene);EditorSceneManager.MarkSceneDirty(scene);Check(EditorSceneManager.SaveScene(scene),"save failed");scene=EditorSceneManager.OpenScene(SceneValidation.ScenePath);SceneValidation.Validate(scene);session=All<PrototypeSession>(scene).Single();foreach(var source in new[]{session.Audio.motor,session.Audio.motorLoad,session.Audio.transmission})Check(source&&source.clip&&source.loop&&!source.playOnAwake&&source.spatialBlend==0&&source.dopplerLevel==0,"saved source binding");Check(session.Audio.brakeAir&&session.Audio.brakeAir.clip&&!session.Audio.brakeAir.loop&&!session.Audio.brakeAir.playOnAwake,"saved brake source");Check(session.Audio.tractorAudio.idle&&session.Audio.loaderAudio.idle&&session.Audio.loaderAudio.work&&session.Audio.loaderAudio.drive,"saved recorded profiles");Check(alarm==AssetDatabase.GetAssetPath(session.Audio.reverseAlarm.clip)&&Mathf.Abs(alarmVolume-session.Audio.reverseAlarm.volume)<.0001f,"reverse alarm preserved");CurveChecks(session.Audio,session.Fleet);MechanicsChecks.Run();Check(seedPath==AssetDatabase.GetAssetPath(session.Snow.seed)&&seedHash==AssetDatabase.GetAssetDependencyHash(seedPath),"snow changed");Check(fleetPoses.SequenceEqual(session.Fleet.Select(m=>m.transform.localToWorldMatrix.ToString("R"))),"fleet moved");foreach(var p in All<CatalogPlacement>(scene))Check(poses[GlobalObjectId.GetGlobalObjectIdSlow(p).ToString()]==p.transform.localToWorldMatrix.ToString("R"),"catalog placement changed");
 File.WriteAllText(Logs+"/Validation.txt","PASS: Unity "+Application.unityVersion+" / "+EditorUserBuildSettings.activeBuildTarget+". "+assertions+" assertions. Six reference-derived mono 24kHz loops and a short pneumatic brake cue, PCM headroom and wrap checks; engine/base load/transmission sources authored and saved/reopened. Direct curve sweep and actual runtime UpdateMachinery checks for tractor/loader: audible idle, speed pitch/gear volume, stationary struggle, load RPM droop, heavier loader tuning/profile swaps, moving-brake edge/cooldown, mute/unmute, pause/resume, fuel/condition/parked/disable silence. Existing reverse warning clip/volume retained. Scene validation and 19 snow checks passed; snow hash, fleet/catalog poses preserved. No player-save writes, physics changes, runtime audio factories or district rebake. No audible listening, live driving, Android packaging or A07 speaker/performance acceptance claimed.");Debug.Log(File.ReadAllText(Logs+"/Validation.txt"));
 }
 }
